// Lazy chunk per provinsi (Vite akan memisah masing-masing jadi chunk sendiri).
const _files = import.meta.glob('./provinsi/*.json');

export function loadProvinsi(kode) {
  const key = `./provinsi/${kode}.json`;
  const loader = _files[key];
  if (!loader) return Promise.reject(new Error('Provinsi tidak ditemukan: ' + kode));
  return loader().then((m) => m.default);
}

export function daftarProvinsi() { return PROVINSI; }
